import json
import math

def get_prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

def main():
    n = 33146799
    prime_factors = get_prime_factors(n)

    # Also verify full factorization with multiplicities
    temp = n
    factorization = {}
    for p in prime_factors:
        count = 0
        while temp % p == 0:
            count += 1
            temp //= p
        factorization[p] = count

    ans_str = ", ".join(str(p) for p in prime_factors)

    result = {
        "final_answer": ans_str,
        "evidence": {
            "number": n,
            "prime_factors": prime_factors,
            "factorization": factorization
        }
    }
    print(json.dumps(result))

if __name__ == "__main__":
    main()
