import json

input_seq = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"

tokens = input_seq.split()

matching = {
    '(': ')',
    '[': ']',
    '{': '}',
    '<': '>'
}

closing = {v: k for k, v in matching.items()}

stack = []
for tok in tokens:
    if tok in matching:
        stack.append(tok)
    elif tok in closing:
        if stack and stack[-1] == closing[tok]:
            stack.pop()
        else:
            raise ValueError(f"Mismatched token: {tok}, stack top: {stack[-1] if stack else None}")

# Remaining tokens to close the sequence
completion = [matching[tok] for tok in reversed(stack)]
final_answer = " ".join(completion)

output = {
    "final_answer": final_answer,
    "evidence": {
        "unmatched_open_brackets": stack,
        "completion": completion
    }
}

print(json.dumps(output))
