# Languages spoken by each:
# Korean: only Korean
# French: French, German
# British: English, Korean
# German: Korean, French, English, German
languages = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "German": {"Korean", "French", "English", "German"},
}


def can_communicate(p1, p2):
    return len(languages[p1].intersection(languages[p2])) > 0


solutions = []

# Enumerate all permutations of room assignments (rooms 1, 2, 3, 4)
for perm in itertools.permutations(
    ["South Korea", "France", "Britain", "Germany"]
):
    room = {perm[i]: i + 1 for i in range(4)}

    # Korean: my room number is larger than the German
    if not (room["South Korea"] > room["German"]):
        continue

    # Korean: nor can I communicate with my neighbors
    k_pos = room["South Korea"] - 1
    k_neighbors = []
    if k_pos > 0:
        k_neighbors.append(perm[k_pos - 1])
    if k_pos < 3:
        k_neighbors.append(perm[k_pos + 1])

    if any(can_communicate("South Korea", neighbor) for neighbor in k_neighbors):
        continue

    # French: I can't communicate with my neighbors
    f_pos = room["France"] - 1
    f_neighbors = []
    if f_pos > 0:
        f_neighbors.append(perm[f_pos - 1])
    if f_pos < 3:
        f_neighbors.append(perm[f_pos + 1])

    if any(can_communicate("France", neighbor) for neighbor in f_neighbors):
        continue

    # British: I can only communicate with one of my neighbors
    b_pos = room["Britain"] - 1
    b_neighbors = []
    if b_pos > 0:
        b_neighbors.append(perm[b_pos - 1])
    if b_pos < 3:
        b_neighbors.append(perm[b_pos + 1])

    comm_b_count = sum(
        1 for neighbor in b_neighbors if can_communicate("Britain", neighbor)
    )
    if comm_b_count != 1:
        continue

    solutions.append(perm)

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

ans_letter = None
for letter, opt in options.items():
    # normalize names for comparison
